mapper.select:
/* AppLeaveApprovalMapper.selectLeaveBalance */
SELECT
      IFNULL(SUM(G.GRANT_DAYS), 0)                      AS granted
    , IFNULL(SUM(G.USED_DAYS), 0)                       AS used
    , IFNULL(SUM(G.GRANT_DAYS) - SUM(G.USED_DAYS), 0)   AS remain
  FROM TB_USER_LEAVE_GRANT G
 WHERE G.CMPNY_CD  = #{cmpnyCd}
   AND G.USER_CD   = #{userCd}
   AND G.LEAVE_CD  = #{leaveCd}
   AND G.STATUS    = 'ACTIVE'
   AND G.EXPIRE_YN = 'N'
   AND G.DEL_YN    = 'N'

/* AppLeaveApprovalMapper.selectMyProcessedLeaveHistory */ SELECT R.REQ_ID AS reqId , AP.APPROVAL_STEP AS approvalStep , R.REQ_TYPE AS reqType , FNC_CMM_INFO_SRCH(R.CMPNY_CD, 'USER_NM', R.USER_CD, null) AS requesterUserNm
, FNC_CMM_INFO_SRCH(R.CMPNY_CD, 'NODE', R.SITE_CD, COALESCE(NULLIF(R.NODE_CD, ''), ( SELECT RU.NODE_CD FROM TB_USER RU WHERE RU.CMPNY_CD = R.CMPNY_CD AND RU.SITE_CD = R.SITE_CD AND RU.USER_CD = R.USER_CD LIMIT 1 ))) AS nodeNm , R.WORK_YMD AS workYmd , LT.LEAVE_NM AS leaveNm , FNC_CMM_INFO_SRCH(R.CMPNY_CD, 'SYST_VAL', U.USE_UNIT_TYPE, 'SYS025') AS unitNm , R.LEAVE_DAYS AS leaveDays , DATE_FORMAT(R.INSERT_DATE, '%Y-%m-%dT%H:%i:%s') AS reqDate , AP.APPROVAL_STATUS AS myDecision , DATE_FORMAT(AP.APPROVAL_DATE, '%Y-%m-%dT%H:%i:%s') AS myProcessDate , AP.APPROVAL_COMMENT AS myComment , R.REQ_STATUS AS reqStatus FROM TB_USER_ATTD_REQ_APPROVAL AP JOIN TB_USER_ATTD_REQ R ON R.CMPNY_CD = AP.CMPNY_CD AND R.REQ_ID = AP.REQ_ID
LEFT JOIN TB_USER_LEAVE_USE U ON U.CMPNY_CD = R.CMPNY_CD AND U.DEL_YN = 'N' AND ( (R.REQ_TYPE = '05' AND U.REQ_ID = R.REQ_ID AND U.LEAVE_STATUS = 'CONFIRMED' AND U.LEAVE_ID = ( SELECT MIN(X.LEAVE_ID) FROM TB_USER_LEAVE_USE X WHERE X.CMPNY_CD = R.CMPNY_CD AND X.REQ_ID = R.REQ_ID AND X.LEAVE_STATUS = 'CONFIRMED' AND X.DEL_YN = 'N' )) OR (R.REQ_TYPE = '06' AND U.LEAVE_ID = R.TARGET_ID) ) LEFT JOIN TB_LEAVE_TYPE_MGMT LT ON LT.CMPNY_CD = U.CMPNY_CD AND LT.LEAVE_CD = U.LEAVE_CD WHERE AP.CMPNY_CD = #{cmpnyCd} AND AP.APPROVER_USER_CD = #{approverUserCd} AND AP.APPROVAL_STATUS IN ('02', '03') AND R.REQ_TYPE IN ('05', '06') AND R.DEL_YN = 'N'
AND DATE_FORMAT(AP.APPROVAL_DATE, '%Y%m%d') >= #{startYmd}
AND DATE_FORMAT(AP.APPROVAL_DATE, '%Y%m%d') <= #{endYmd}
AND ( R.USER_CD LIKE CONCAT('%', #{keyword}, '%') OR FNC_CMM_INFO_SRCH(R.CMPNY_CD, 'USER_NM', R.USER_CD, null) LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY AP.APPROVAL_DATE DESC LIMIT #{limit} OFFSET #{offset}

/* AppLeaveApprovalMapper.countMyProcessedLeaveHistory */
SELECT COUNT(1)
  FROM TB_USER_ATTD_REQ_APPROVAL AP
  JOIN TB_USER_ATTD_REQ R
    ON R.CMPNY_CD = AP.CMPNY_CD
   AND R.REQ_ID   = AP.REQ_ID
 WHERE AP.CMPNY_CD         = #{cmpnyCd}
   AND AP.APPROVER_USER_CD = #{approverUserCd}
   AND AP.APPROVAL_STATUS IN ('02', '03')
   AND R.REQ_TYPE IN ('05', '06')
   AND R.DEL_YN            = 'N'

   AND DATE_FORMAT(AP.APPROVAL_DATE, '%Y%m%d') >= #{startYmd}


   AND DATE_FORMAT(AP.APPROVAL_DATE, '%Y%m%d') <= #{endYmd}


   AND (
         R.USER_CD LIKE CONCAT('%', #{keyword}, '%')
      OR FNC_CMM_INFO_SRCH(R.CMPNY_CD, 'USER_NM', R.USER_CD, null) LIKE CONCAT('%', #{keyword}, '%')
   )
